struct customer { char *name, *region; };

/* enrich: add customer fields for the id already in the message */
enum enrich_status enrich_order(struct order *msg, struct source *src) {
    struct customer c;
    if (source_lookup(src, msg->customer_id, &c) != SOURCE_OK)
        return ENRICH_UNAVAILABLE;            /* distinct from 'not found' */
    msg->customer_name = strdup(c.name);      /* caller owns the copy */
    msg->region        = strdup(c.region);
    return ENRICH_OK;
}
